# Homebrew formula for the Engra CLI. Generated by packaging/release.py in the
# release workflow; do not hand-edit. Release assets live in
# arenberg-engineering/engra-releases.
class Engra < Formula
  desc "AI coding agent and developer assistant for the terminal"
  homepage "https://engra.io"
  # Proprietary software of Arenberg AG, all rights reserved (LICENSE.txt).
  license :cannot_represent

  livecheck do
    url :stable
    strategy :github_latest
  end

  on_macos do
    on_arm do
      url "https://github.com/arenberg-engineering/engra-releases/releases/download/v0.2.0/engra-0.2.0-macos-arm64.tar.gz"
      sha256 "1b68756fef7f817cf2eb1ce7626aa1a2a283641796014fd25143d29fa4e5eab6"
    end
    on_intel do
      url "https://github.com/arenberg-engineering/engra-releases/releases/download/v0.2.0/engra-0.2.0-macos-x64.tar.gz"
      sha256 "f76bd69aa8d9f684537e84c9d221004b5189e05c6b3c5687b48445e952707600"
    end
  end

  on_linux do
    on_arm do
      url "https://github.com/arenberg-engineering/engra-releases/releases/download/v0.2.0/engra-0.2.0-linux-arm64.tar.gz"
      sha256 "87096dadc31f38f52272eec1bbce858d4b70cac7fb0b4d50fb7c93a42f9fb505"
    end
    on_intel do
      url "https://github.com/arenberg-engineering/engra-releases/releases/download/v0.2.0/engra-0.2.0-linux-x64.tar.gz"
      sha256 "0941a264d0f7d162c3e7eb2e606a50036fce7ddbc75dcd7bba6021842aedbdd2"
    end
  end

  def install
    bin.install "engra"
    prefix.install "LICENSE.txt", "TERMS.md", "THIRD_PARTY_NOTICES.txt"
  end

  def caveats
    <<~EOS
      Sign in with:
        engra login

      Terms of Use: engra legal --terms

      Before uninstalling, run `engra logout` to remove saved credentials from
      the OS keychain. Settings and link state stay in ~/.config/engra (and
      doctor records in ~/.engra); remove them to clear everything.
    EOS
  end

  test do
    assert_equal "engra #{version}", shell_output("#{bin}/engra --version").strip
    assert_match "doctor", shell_output("#{bin}/engra --help")
    assert_match "Arenberg AG", shell_output("#{bin}/engra legal")
  end
end
